export const notesHtml = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Colosseum 1.1.10 — Release notes</title>\n<style>body{margin:0;background:#101114;color:#e7e5de;font:18px/1.7 system-ui,sans-serif}main{max-width:780px;margin:auto;padding:48px 24px 96px}a{color:#f3ce4b}nav{font-size:15px;margin-bottom:48px}h1{font-size:clamp(32px,6vw,52px);line-height:1.15}h2{font-size:25px;margin-top:48px;color:#f3ce4b}li{padding:5px 0}code{overflow-wrap:anywhere;font-size:.9em}</style>\n</head><body><main><nav><a href=\"/\">Colosseum</a> / Release notes</nav><article><h1>Colosseum 1.1.10</h1>\n<p>Vault now opens with its own background. Configurable Tankoyomi and Tankorent add-ons use online delivery while downloads and torrent handling stay on your device. MangaSin can be enabled as an optional Tankoyomi source, and playback retries preserve the current position.</p>\n<h2>Vault</h2>\n<ul><li>Vault opens with its own background instead of leaving the previous world visible underneath.</li></ul>\n<h2>Add-on delivery</h2>\n<ul><li>Tankoyomi and Tankorent use Workers for online add-on delivery while downloads and torrent handling stay on your device.</li><li>Existing source settings are preserved.</li></ul>\n<h2>MangaSin</h2>\n<ul><li>Enable MangaSin in Tankoyomi to search and read directly from your device, with signed add-on updates.</li><li>The source is optional and starts disabled.</li></ul>\n<h2>Playback</h2>\n<ul><li>The video player handles loading failures and preserves the playback position when retrying a failed stream.</li></ul>\n<h2>Linux accounts</h2>\n<ul><li>Accounts use the desktop Secret Service keyring.</li><li>Locked or unavailable keyrings return an error without claiming credentials were deleted.</li></ul>\n<h2>Updates</h2>\n<ul><li>Windows update ordering recognizes 1.1.10 as newer than 1.1.9.</li><li>Linux updates remain manual.</li></ul></article></main></body></html>\n";
